/* Generated by cider-plugin/scripts/bundle.mjs. Edit lib/core.mjs and src/cider-host.js. */
const PLUGIN_VERSION = "0.1.0"
const USER_AGENT = "AppleMusicTranslator/0.1 (https://github.com/jpark9013/AppleMusicTranslator)"
const LRCLIB_BASE = "https://lrclib.net/api"
const DEEPSEEK_ENDPOINT = "https://api.deepseek.com/chat/completions"
const DEFAULT_MODEL = "deepseek-flash"
const MAX_DURATION_DIFFERENCE = 5
const TIMESTAMP = /\[(\d+):(\d{1,2}(?:[.:]\d{1,3})?)\]/g

class LyricsError extends Error {
  constructor(message = "No lyrics found for this song.") {
    super(message)
    this.name = "LyricsError"
  }
}

class TranslationError extends Error {
  constructor(code, message) {
    super(message)
    this.name = "TranslationError"
    this.code = code
  }

  get isRetryable() {
    if (this.code === "malformed") return true
    if (this.code === "missing-key") return false
    const status = Number(this.code)
    return status === 429 || status >= 500
  }
}

function cacheKey(track) {
  return `${track.artist}|${track.name}`.toLowerCase()
}

const NAMED_ENTITIES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " }

// Some lyric providers send HTML-escaped text ("&amp;", "&#8211;") that Cider
// shows verbatim.
function decodeEntities(text) {
  return String(text ?? "").replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, code) => {
    if (code[0] !== "#") return NAMED_ENTITIES[code.toLowerCase()] ?? match
    const point = code[1].toLowerCase() === "x" ? parseInt(code.slice(2), 16) : Number(code.slice(1))
    return point > 0 && point <= 0x10ffff ? String.fromCodePoint(point) : match
  })
}

// Lyric sources disagree on spacing and punctuation ("줄래" vs "줄래?"), and
// Cider renders words in separate spans, so lines are compared without them.
function lineKey(text) {
  return decodeEntities(text).normalize("NFKC").replace(/[\p{P}\p{S}\s]+/gu, "").toLowerCase()
}

// Maps official {line, translation} pairs onto the displayed lines. Sources
// sometimes join two displayed lines into one, so a line that has no match on
// its own is tried together with the next line.
function alignTranslations(lineTexts, pairs) {
  const official = new Map()
  for (const { line, translation } of pairs) {
    if (translation) official.set(lineKey(line), translation)
  }
  const byKey = {}
  for (let i = 0; i < lineTexts.length; i += 1) {
    const key = lineKey(lineTexts[i])
    if (!key || byKey[key]) continue
    if (official.has(key)) {
      byKey[key] = official.get(key)
    } else if (i + 1 < lineTexts.length && official.has(key + lineKey(lineTexts[i + 1]))) {
      byKey[key] = official.get(key + lineKey(lineTexts[i + 1]))
    }
  }
  return byKey
}

function translationsByLineKey(translations) {
  const byKey = {}
  for (const [line, translation] of Object.entries(translations)) {
    if (translation) byKey[lineKey(line)] = translation
  }
  return byKey
}

function parseLRC(lrc) {
  const lines = []
  for (const rawLine of lrc.split(/\r?\n/)) {
    const matches = [...rawLine.matchAll(TIMESTAMP)]
    if (matches.length === 0) continue
    const last = matches[matches.length - 1]
    const text = rawLine.slice(last.index + last[0].length).trim()
    for (const match of matches) {
      const minutes = Number(match[1])
      const seconds = Number(match[2].replace(":", "."))
      lines.push({ time: minutes * 60 + seconds, text, order: lines.length })
    }
  }
  lines.sort((a, b) => a.time - b.time || a.order - b.order)
  return lines.map(({ time, text }) => ({ time, text }))
}

function activeLineIndex(lyrics, position, lead = 0) {
  if (!lyrics?.isSynced) return null
  const target = position + lead
  let index = null
  lyrics.lines.forEach((line, i) => {
    if ((line.time ?? 0) <= target) index = i
  })
  return index
}

function simplifiedTitle(title) {
  let result = title.replace(/\s*[([{][^)\]}]*[)\]}]/g, "")
  const dash = result.indexOf(" - ")
  if (dash !== -1) result = result.slice(0, dash)
  const trimmed = result.trim()
  return trimmed === "" ? title : trimmed
}

function lyricsFromRecord(record) {
  if (record.instrumental === true) {
    return { lines: [], isSynced: false, isInstrumental: true }
  }
  if (record.syncedLyrics) {
    const lines = parseLRC(record.syncedLyrics)
    if (lines.length > 0) return { lines, isSynced: true, isInstrumental: false }
  }
  if (record.plainLyrics) {
    const lines = record.plainLyrics.split(/\r?\n/).map((text) => ({
      time: null,
      text: text.trim(),
    }))
    return { lines, isSynced: false, isInstrumental: false }
  }
  return null
}

function bestMatch(records, duration) {
  const candidates = records.filter((record) => {
    if (!(duration > 0) || record.duration == null) return true
    return Math.abs(record.duration - duration) <= MAX_DURATION_DIFFERENCE
  })
  return (
    candidates.find((record) => record.syncedLyrics) ||
    candidates.find((record) => record.plainLyrics) ||
    candidates.find((record) => record.instrumental === true) ||
    null
  )
}

function uniqueLines(lines) {
  const seen = new Set()
  return lines.filter((line) => line && !seen.has(line) && seen.add(line))
}

function parseTranslations(text) {
  const start = text.indexOf("{")
  const end = text.lastIndexOf("}")
  if (start === -1 || end <= start) return null
  try {
    const object = JSON.parse(text.slice(start, end + 1))
    if (!Array.isArray(object.translations)) return null
    return object.translations.map((value) => String(value ?? "").trim())
  } catch {
    return null
  }
}

function systemPrompt(language, count) {
  return [
    `You translate song lyrics into ${language} for display under the original lines while the song plays.`,
    "Translate meaning, tone and imagery naturally, the way a skilled human lyric translator would, rather than word for word.",
    "Keep each translation on a single line and roughly as concise as the original.",
    `If a line is already in ${language}, or is only vocalizations like "oh" or "la la", return an empty string for it.`,
    `Respond with only a JSON object of the form {"translations": ["...", "..."]} containing exactly ${count} strings, one per input line, in the same order. No commentary, no code fences.`,
  ].join("\n")
}

function requestBody(lines, track, language, model, stream = false) {
  return {
    model,
    max_tokens: 8192,
    response_format: { type: "json_object" },
    // Reasoning made up ~85-90% of output tokens with no gain for this task.
    thinking: { type: "disabled" },
    ...(stream ? { stream: true } : {}),
    messages: [
      { role: "system", content: systemPrompt(language, lines.length) },
      {
        role: "user",
        content: `Song: "${track.name}" by ${track.artist}\nLines (${lines.length}):\n${JSON.stringify(lines)}`,
      },
    ],
  }
}

function query(params) {
  return new URLSearchParams(
    Object.entries(params).filter(([, value]) => value != null && value !== "")
  ).toString()
}

async function getJSON(url, http) {
  const { status, body } = await http(url, {
    headers: { "User-Agent": USER_AGENT },
  })
  if (status !== 200) return { status, data: null }
  return { status, data: JSON.parse(body) }
}

async function fetchLyrics(track, http) {
  const exactURL = `${LRCLIB_BASE}/get?${query({
    track_name: track.name,
    artist_name: track.artist,
    album_name: track.album,
    duration: track.duration > 0 ? String(Math.round(track.duration)) : undefined,
  })}`
  const exact = await getJSON(exactURL, http)
  const exactLyrics = exact.data ? lyricsFromRecord(exact.data) : null
  if (exactLyrics) return exactLyrics

  const titles = [track.name]
  const simplified = simplifiedTitle(track.name)
  if (simplified !== track.name) titles.push(simplified)

  for (const title of titles) {
    const searchURL = `${LRCLIB_BASE}/search?${query({
      track_name: title,
      artist_name: track.artist,
    })}`
    const search = await getJSON(searchURL, http)
    if (!Array.isArray(search.data)) continue
    const match = bestMatch(search.data, track.duration)
    const lyrics = match ? lyricsFromRecord(match) : null
    if (lyrics) return lyrics
  }
  throw new LyricsError()
}

async function translateLines(lines, track, language, model, apiKey, http) {
  if (!apiKey) throw new TranslationError("missing-key", "Add your DeepSeek API key to see translations.")
  const unique = uniqueLines(lines)
  if (unique.length === 0) return {}

  let lastError = new TranslationError("malformed", "Translation failed: the model returned an unexpected response.")
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      const translated = await sendTranslation(unique, track, language, model, apiKey, http)
      return Object.fromEntries(unique.map((line, index) => [line, translated[index]]))
    } catch (error) {
      if (!(error instanceof TranslationError) || !error.isRetryable) throw error
      lastError = error
    }
  }
  throw lastError
}

function deepseekHeaders(apiKey) {
  return {
    Authorization: `Bearer ${apiKey}`,
    "content-type": "application/json",
  }
}

function assistantText(json) {
  return json?.choices?.[0]?.message?.content ?? ""
}

async function sendTranslation(lines, track, language, model, apiKey, http) {
  const { status, body } = await http(DEEPSEEK_ENDPOINT, {
    method: "POST",
    headers: deepseekHeaders(apiKey),
    body: JSON.stringify(requestBody(lines, track, language, model)),
  })
  const json = safeJSON(body)
  if (status !== 200) {
    throw new TranslationError(status, json?.error?.message || body || "Unknown error")
  }
  const text = assistantText(json)
  const translations = parseTranslations(text)
  if (!translations && !text.includes('"translations"')) throw declinedError()
  if (!translations || translations.length !== lines.length) {
    throw new TranslationError("malformed", "Translation failed: the model returned an unexpected response.")
  }
  return translations
}

// Pulls each finished string out of a partial {"translations": [...]} reply so
// lines can be shown while the rest of the response is still streaming.
// The model answered in prose instead of the requested JSON, e.g. it chose not
// to translate the song. Retrying the same request would not change that.
function declinedError() {
  return new TranslationError("declined", "The model didn't translate this song.")
}

function createTranslationStreamParser() {
  let buffer = ""
  let cursor = -1
  let emitted = 0
  return {
    push(chunk) {
      buffer += chunk
      const found = []
      if (cursor === -1) {
        const key = buffer.indexOf('"translations"')
        const open = key === -1 ? -1 : buffer.indexOf("[", key)
        if (open === -1) return found
        cursor = open + 1
      }
      while (cursor < buffer.length) {
        const start = buffer.indexOf('"', cursor)
        if (start === -1) {
          cursor = buffer.length
          break
        }
        const close = buffer.slice(cursor, start).indexOf("]")
        if (close !== -1) {
          cursor = buffer.length
          break
        }
        let end = start + 1
        while (end < buffer.length && buffer[end] !== '"') end += buffer[end] === "\\" ? 2 : 1
        if (end >= buffer.length) break
        try {
          found.push({ index: emitted, text: String(JSON.parse(buffer.slice(start, end + 1))).trim() })
        } catch {
          found.push({ index: emitted, text: "" })
        }
        emitted += 1
        cursor = end + 1
      }
      return found
    },
    get count() {
      return emitted
    },
    get started() {
      return cursor !== -1
    },
  }
}

// Splits DeepSeek/OpenAI server-sent events into text deltas.
function createSSEParser() {
  let buffer = ""
  return function push(chunk) {
    buffer += chunk.replace(/\r\n/g, "\n")
    const events = buffer.split("\n\n")
    buffer = events.pop()
    const deltas = []
    for (const event of events) {
      const data = event
        .split("\n")
        .filter((line) => line.startsWith("data:"))
        .map((line) => line.slice(5).trim())
        .join("")
      if (!data || data === "[DONE]") continue
      const json = safeJSON(data)
      if (json?.error) {
        const status = json.error.code === "overloaded" || json.error.type === "overloaded_error" ? 529 : 500
        throw new TranslationError(status, json.error.message || "Stream error")
      }
      const text = json?.choices?.[0]?.delta?.content
      if (text) deltas.push(text)
    }
    return deltas
  }
}

// Streams a translation and calls onTranslation(line, translation) as each
// line arrives. Falls back to one non-streaming retry when the stream fails.
async function streamTranslateLines(lines, track, language, model, apiKey, fetchImpl, onTranslation = () => {}) {
  if (!apiKey) throw new TranslationError("missing-key", "Add your DeepSeek API key to see translations.")
  const unique = uniqueLines(lines)
  if (unique.length === 0) return {}

  const result = {}
  try {
    const response = await fetchImpl(DEEPSEEK_ENDPOINT, {
      method: "POST",
      headers: deepseekHeaders(apiKey),
      body: JSON.stringify(requestBody(unique, track, language, model, true)),
    })
    if (response.status !== 200) {
      const body = await response.text()
      throw new TranslationError(response.status, safeJSON(body)?.error?.message || body || "Unknown error")
    }
    const sse = createSSEParser()
    const parser = createTranslationStreamParser()
    const decoder = new TextDecoder()
    const reader = response.body.getReader()
    for (;;) {
      const { done, value } = await reader.read()
      const text = done ? decoder.decode() : decoder.decode(value, { stream: true })
      for (const delta of sse(text)) {
        for (const { index, text: translation } of parser.push(delta)) {
          if (index >= unique.length) continue
          result[unique[index]] = translation
          if (translation) onTranslation(unique[index], translation)
        }
      }
      if (done) break
    }
    if (parser.count === unique.length) return result
    if (!parser.started) throw declinedError()
  } catch (error) {
    if (!(error instanceof TranslationError) || !error.isRetryable) throw error
  }

  const retried = await translateLines(unique, track, language, model, apiKey, async (url, options) => {
    const response = await fetchImpl(url, options)
    return { status: response.status, body: await response.text() }
  })
  for (const [line, translation] of Object.entries(retried)) {
    if (translation && result[line] !== translation) onTranslation(line, translation)
  }
  return retried
}

// Writes translations onto Cider's lyric line objects. Lines that already
// carry a translation we did not write (Cider's own) are left alone.
function applyTranslationsToLines(lines, translationsByKey, owned) {
  let applied = 0
  for (const line of lines ?? []) {
    if (!line || typeof line.text !== "string") continue
    const translation = translationsByKey[lineKey(line.text)]
    if (!translation) continue
    const current = line.translation
    const ours = owned.get(line)
    if (current && current !== ours) continue
    if (current !== translation) line.translation = translation
    owned.set(line, translation)
    applied += 1
  }
  return applied
}

function clearOwnedTranslations(lines, owned) {
  for (const line of lines ?? []) {
    if (!line || !owned.has(line)) continue
    if (line.translation === owned.get(line)) line.translation = ""
    owned.delete(line)
  }
}

function hasForeignTranslations(lines, owned) {
  return (lines ?? []).some((line) => line?.translation && line.translation !== owned.get(line))
}

function createPersistentCache(storage, limit = 300) {
  const prefix = "amt:v1:"
  const indexKey = `${prefix}index`
  const readIndex = () => {
    try {
      return JSON.parse(storage.getItem(indexKey) || "[]")
    } catch {
      return []
    }
  }
  return {
    get(songId, language) {
      try {
        return JSON.parse(storage.getItem(`${prefix}${songId}|${language}`) || "null")
      } catch {
        return null
      }
    },
    set(songId, language, translationsByKey) {
      const key = `${songId}|${language}`
      const index = readIndex().filter((entry) => entry !== key)
      index.push(key)
      while (index.length > limit) storage.removeItem(`${prefix}${index.shift()}`)
      try {
        storage.setItem(`${prefix}${key}`, JSON.stringify(translationsByKey))
        storage.setItem(indexKey, JSON.stringify(index))
      } catch {}
    },
  }
}

function safeJSON(text) {
  try {
    return JSON.parse(text)
  } catch {
    return null
  }
}

function createMemoryCache() {
  const store = new Map()
  return {
    lyrics(track) {
      return store.get(`lyrics|${cacheKey(track)}`) ?? null
    },
    storeLyrics(lyrics, track) {
      store.set(`lyrics|${cacheKey(track)}`, lyrics)
    },
    translations(track, language) {
      return store.get(`translation|${cacheKey(track)}|${language}`) ?? null
    },
    storeTranslations(translations, track, language) {
      store.set(`translation|${cacheKey(track)}|${language}`, translations)
    },
  }
}

// displayedLines returns the lines the player already shows; they are
// translated when LRCLIB has no lyrics for the track.
async function loadTranslatedLyrics(
  track,
  settings,
  http,
  cache = createMemoryCache(),
  displayedLines = () => []
) {
  let lyrics = cache.lyrics(track)
  if (!lyrics) {
    try {
      lyrics = await fetchLyrics(track, http)
    } catch (error) {
      const shown = error instanceof LyricsError ? uniqueLines(displayedLines()) : []
      if (shown.length === 0) throw error
      lyrics = { lines: shown.map((text) => ({ time: null, text })), isSynced: false, isInstrumental: false }
    }
    cache.storeLyrics(lyrics, track)
  }
  if (lyrics.isInstrumental) return { lyrics, translations: {}, error: null }

  let translations = cache.translations(track, settings.language)
  let error = null
  if (!translations) {
    try {
      translations = await translateLines(
        lyrics.lines.map((line) => line.text),
        track,
        settings.language,
        settings.model,
        settings.apiKey,
        http
      )
      cache.storeTranslations(translations, track, settings.language)
    } catch (caught) {
      translations = {}
      error = caught.message
    }
  }
  return { lyrics, translations, error }
}

function defaultSettings() {
  return {
    language: "English",
    model: DEFAULT_MODEL,
    apiKey: "",
    enabled: true,
  }
}

const RISE_LYRICS_API = "https://exp-rise.cider.sh/api/v1/lyrics"
const NETEASE_API = "https://music.163.com/api/"

// Identifies Cider's lookups to lyric providers other than Apple Music:
// user-submitted lyrics and Musixmatch (both through Cider's Rise server) and
// NetEase. Translation requests are not matched.
function thirdPartyLyricsRequest(url, body) {
  const href = String(url)
  if (href.startsWith(`${RISE_LYRICS_API}/user/`)) {
    const id = href.slice(`${RISE_LYRICS_API}/user/`.length).split(/[/?#]/)[0]
    return { provider: "user", id: decodeURIComponent(id), name: null }
  }
  if (href.startsWith(`${RISE_LYRICS_API}/mxm`)) {
    const json = typeof body === "string" ? safeJSON(body) : null
    return { provider: "musixmatch", id: json?.id != null ? String(json.id) : null, name: json?.name ?? null }
  }
  if (href.startsWith(NETEASE_API)) {
    let query = ""
    try {
      query = [...new URL(href).searchParams.values()].join(" ")
    } catch {}
    return { provider: "netease", id: null, name: null, query }
  }
  return null
}

// Text of each <p> line in a TTML lyrics document, in order.
function ttmlLineTexts(ttml) {
  return [...String(ttml ?? "").matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/g)].map((match) =>
    decodeEntities(match[1].replace(/<br\s*\/?>/g, " ").replace(/<[^>]+>/g, "")).replace(/\s+/g, " ").trim()
  )
}

// Pairs an original TTML with Cider's machine-translated copy of it.
function pairsFromTranslatedTtml(original, translated) {
  const source = ttmlLineTexts(original)
  const target = ttmlLineTexts(translated)
  const pairs = []
  for (let i = 0; i < Math.min(source.length, target.length); i += 1) {
    if (source[i] && target[i] && source[i] !== target[i]) pairs.push({ line: source[i], translation: target[i] })
  }
  return pairs
}

const SCRIPTS = [
  ["ko", /\p{Script=Hangul}/u],
  ["ja", /[\p{Script=Hiragana}\p{Script=Katakana}]/u],
  ["zh", /\p{Script=Han}/u],
  ["ru", /\p{Script=Cyrillic}/u],
  ["ar", /\p{Script=Arabic}/u],
  ["he", /\p{Script=Hebrew}/u],
  ["th", /\p{Script=Thai}/u],
  ["el", /\p{Script=Greek}/u],
  ["hi", /\p{Script=Devanagari}/u],
]

// Guesses the lyrics language from its script, since providers often label
// Korean or Japanese lyrics as English. Latin-script lyrics fall back to the
// provider's label. Japanese uses Han characters too, so any kana wins.
function detectLanguage(lines, fallback = "en") {
  const counts = new Map()
  let letters = 0
  for (const char of lines.join("")) {
    if (!/\p{L}/u.test(char)) continue
    letters += 1
    for (const [code, pattern] of SCRIPTS) {
      if (pattern.test(char)) {
        counts.set(code, (counts.get(code) ?? 0) + 1)
        break
      }
    }
  }
  if ((counts.get("ja") ?? 0) > 0 && (counts.get("ja") + (counts.get("zh") ?? 0)) / letters >= 0.15) return "ja"
  let best = null
  for (const [code, count] of counts) if (!best || count > counts.get(best)) best = code
  return best && counts.get(best) / letters >= 0.15 ? best : (fallback || "en").split(/[-_]/)[0].toLowerCase()
}

const VOCALIZATION = /^(?:(?:oh+|ah+|la|na|yeah|ye|woo+|ooh+|hey|uh|mm+|da|ba|du|eh)[\s,!.~…-]*)+$/i
const NON_LATIN_LETTER = /[^\p{Script=Latin}\p{P}\p{S}\p{N}\s]/u

// Drops lines the model would only return blank for, before they are sent:
// vocalizations, and Latin-script lines when translating into English.
function linesToTranslate(lines, language) {
  return uniqueLines(lines.map((line) => String(line ?? "").trim())).filter((line) => {
    if (VOCALIZATION.test(line)) return false
    if (language === "English" && !NON_LATIN_LETTER.test(line)) return false
    return true
  })
}

// ISO 639-1 codes Cider uses to look up official translations.
const LANGUAGE_CODES = {
  English: "en", Spanish: "es", French: "fr", German: "de", Italian: "it", Portuguese: "pt",
  Dutch: "nl", Swedish: "sv", Polish: "pl", Russian: "ru", Ukrainian: "uk", Turkish: "tr",
  Greek: "el", Arabic: "ar", Hebrew: "he", Hindi: "hi", Indonesian: "id", Vietnamese: "vi",
  Thai: "th", Japanese: "ja", Korean: "ko", "Chinese (Simplified)": "zh", Tagalog: "tl",
}

const LANGUAGES = [
  "English", "Spanish", "French", "German", "Italian", "Portuguese", "Dutch",
  "Swedish", "Polish", "Russian", "Ukrainian", "Turkish", "Greek", "Arabic",
  "Hebrew", "Hindi", "Indonesian", "Vietnamese", "Thai", "Japanese", "Korean",
  "Chinese (Simplified)", "Chinese (Traditional)", "Tagalog",
]

const SETTINGS_KEY = "apple-music-translator.settings"
const STYLE_ID = "amt-translator-style"

function loadSettings() {
  try {
    const settings = { ...defaultSettings(), ...JSON.parse(localStorage.getItem(SETTINGS_KEY) || "{}") }
    if (/claude|haiku/i.test(settings.model || "")) settings.model = DEFAULT_MODEL
    return settings
  } catch {
    return defaultSettings()
  }
}

function saveSettings(settings) {
  localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings))
}

function browserHTTP(url, options = {}) {
  return fetch(url, options).then(async (response) => ({
    status: response.status,
    body: await response.text(),
  }))
}

function appleMusicStore() {
  return window.__PLUGINSYS__?.Stores?.appleMusicStore ?? null
}

function ciderStore(id) {
  return window.CiderApp?.store?._s?.get?.(id) ?? null
}

// Same id Cider uses as songId in its lyric store (catalog id for library songs).
function songId(item) {
  return (
    item?.songId ??
    item?.attributes?.playParams?.catalogId ??
    item?.relationships?.catalog?.data?.[0]?.id ??
    item?.id ??
    null
  )
}

function trackInfo(item) {
  return { name: item?.attributes?.name ?? "", artist: item?.attributes?.artistName ?? "" }
}

// The playing song first, then the next queued song so its translation is
// ready before it starts (Cider preloads the next song's lyrics).
function wantedSongs() {
  const songs = []
  const current = appleMusicStore()?.nowPlayingItem
  if (songId(current)) songs.push({ id: String(songId(current)), track: trackInfo(current) })
  const provider = ciderStore("provider-store")?.getCurrentProviderStore?.()
  const next = provider?.queue?.[(provider?.queuePosition ?? -1) + 1]?.track
  if (songId(next) && String(songId(next)) !== songs[0]?.id) {
    songs.push({ id: String(songId(next)), track: trackInfo(next) })
  }
  return songs
}

function withTimeout(promise, ms) {
  return Promise.race([promise, new Promise((resolve) => setTimeout(() => resolve(null), ms))])
}

function nowPlayingTrack() {
  const item =
    appleMusicStore()?.nowPlayingItem ||
    window.CiderApp?.RPC?.nowPlayingAttributes ||
    window.MusicKit?.getInstance?.()?.nowPlayingItem ||
    null
  if (!item) return null
  const name = item.name || item.title || item.attributes?.name
  const artist = item.artistName || item.artist || item.attributes?.artistName
  if (!name || !artist) return null
  const millis = item.durationInMillis ?? item.attributes?.durationInMillis
  const duration = millis != null ? millis / 1000 : Number(item.duration || 0)
  return {
    name,
    artist,
    album: item.albumName || item.album || item.attributes?.albumName || "",
    duration: Number.isFinite(duration) ? duration : 0,
  }
}

function ensureStyles() {
  if (document.getElementById(STYLE_ID)) return
  const style = document.createElement("style")
  style.id = STYLE_ID
  style.textContent = `
    .amt-translation {
      display: block;
      margin-top: 0.2em;
      font-size: 0.72em;
      font-weight: 600;
      opacity: 0.72;
      line-height: 1.25;
    }
    .amt-settings {
      display: grid;
      gap: 10px;
      min-width: 280px;
      padding: 12px;
      font: 13px/1.4 system-ui, sans-serif;
    }
    .amt-settings label { display: grid; gap: 4px; }
    .amt-settings input, .amt-settings select { width: 100%; box-sizing: border-box; }
    .amt-settings .amt-inline { display: flex; align-items: center; gap: 6px; }
    .amt-settings .amt-inline input { width: auto; }
    .amt-buttons { display: flex; flex-wrap: wrap; gap: 6px; }
    .amt-status { opacity: 0.7; overflow-wrap: anywhere; }
  `
  document.head.appendChild(style)
}

function lyricNodes() {
  const selectors = [
    ".lyric-line",
    ".lyrics-line",
    "[data-lyric-line]",
    ".lyrics__line",
    ".lyricLine",
  ]
  for (const selector of selectors) {
    const nodes = [...document.querySelectorAll(selector)].filter(
      (node) => !node.classList.contains("amt-translation")
    )
    if (nodes.length > 0) return nodes
  }
  return []
}

// Reads only the original lyric, not Cider's own translation or ours. Cider
// puts each word in its own span, so words are joined with spaces.
function originalText(node) {
  const source = node.querySelector(".lyric-text")
  if (source) {
    const words = source.children.length > 0 ? [...source.children].map((child) => child.textContent) : [source.textContent]
    return decodeEntities(words.join(" ")).replace(/\s+/g, " ").trim()
  }
  const clone = node.cloneNode(true)
  clone.querySelectorAll(".amt-translation, .lyric-text-translated").forEach((child) => child.remove())
  return decodeEntities(clone.textContent).replace(/\s+/g, " ").trim()
}

function displayedLines() {
  return lyricNodes().map(originalText)
}

function displayedSignature() {
  return lineKey(displayedLines().join("\n"))
}

function decodeLyricEntities() {
  for (const node of lyricNodes()) {
    const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT)
    for (let text = walker.nextNode(); text; text = walker.nextNode()) {
      if (!text.data.includes("&") || text.parentElement?.closest(".amt-translation")) continue
      const decoded = decodeEntities(text.data)
      if (decoded !== text.data) text.data = decoded
    }
  }
}

function injectTranslations(translationsByKey) {
  ensureStyles()
  for (const node of lyricNodes()) {
    const translation = translationsByKey[lineKey(originalText(node))]
    let label = node.querySelector(":scope > .amt-translation")
    if (!translation) {
      label?.remove()
      continue
    }
    if (!label) {
      label = document.createElement("span")
      label.className = "amt-translation"
      node.appendChild(label)
    }
    if (label.textContent !== translation) label.textContent = translation
  }
}

function keyHint(apiKey) {
  return apiKey ? `Key saved, ending in …${apiKey.slice(-4)}` : "No API key yet. DeepSeek translations need one."
}

// Lists models, which costs no tokens, to confirm the key is accepted.
async function checkAPIKey(apiKey) {
  try {
    const response = await fetch("https://api.deepseek.com/models", {
      headers: { Authorization: `Bearer ${apiKey}` },
    })
    if (response.ok) return "Key works."
    const body = await response.json().catch(() => null)
    return `Key rejected: ${body?.error?.message || `HTTP ${response.status}`}`
  } catch (error) {
    return `Could not reach DeepSeek: ${error.message}`
  }
}

function element(tag, properties = {}, children = []) {
  const node = Object.assign(document.createElement(tag), properties)
  node.append(...children)
  return node
}

// The saved key is never written into the page; the form only shows its last
// four characters and takes a new key in an empty password field.
function createSettingsElement() {
  if (customElements.get("amt-translator-settings")) return
  customElements.define(
    "amt-translator-settings",
    class extends HTMLElement {
      connectedCallback() {
        const settings = loadSettings()
        const changed = () => this.dispatchEvent(new CustomEvent("amt-settings-changed", { bubbles: true }))
        const update = (patch) => {
          saveSettings({ ...loadSettings(), ...patch })
          changed()
        }

        const status = element("div", { className: "amt-status", textContent: keyHint(settings.apiKey) })
        const keyInput = element("input", { type: "password", placeholder: "sk-...", autocomplete: "off", spellcheck: false })
        const saveKey = element("button", { type: "button", textContent: "Save key" })
        const testKey = element("button", { type: "button", textContent: "Check key" })
        const removeKey = element("button", { type: "button", textContent: "Remove key" })

        saveKey.addEventListener("click", async () => {
          const apiKey = keyInput.value.trim()
          if (!apiKey) return
          keyInput.value = ""
          update({ apiKey })
          status.textContent = `${keyHint(apiKey)}. Checking…`
          status.textContent = `${keyHint(apiKey)}. ${await checkAPIKey(apiKey)}`
        })
        keyInput.addEventListener("keydown", (event) => {
          if (event.key === "Enter") saveKey.click()
        })
        testKey.addEventListener("click", async () => {
          const { apiKey } = loadSettings()
          if (!apiKey) return
          status.textContent = `${keyHint(apiKey)}. Checking…`
          status.textContent = `${keyHint(apiKey)}. ${await checkAPIKey(apiKey)}`
        })
        removeKey.addEventListener("click", () => {
          update({ apiKey: "" })
          status.textContent = keyHint("")
        })

        const language = element(
          "select",
          {},
          LANGUAGES.map((name) => element("option", { value: name, textContent: name, selected: name === settings.language }))
        )
        language.addEventListener("change", () => update({ language: language.value }))
        const model = element("input", { value: settings.model, spellcheck: false })
        model.addEventListener("change", () => update({ model: model.value.trim() || defaultSettings().model }))
        const enabled = element("input", { type: "checkbox", checked: settings.enabled })
        enabled.addEventListener("change", () => update({ enabled: enabled.checked }))

        this.replaceChildren(
          element("div", { className: "amt-settings" }, [
            element("strong", { textContent: "Lyrics Translator" }),
            element("label", {}, [document.createTextNode("DeepSeek API key"), keyInput]),
            element("div", { className: "amt-buttons" }, [saveKey, testKey, removeKey]),
            status,
            element("label", {}, [document.createTextNode("Translate to"), language]),
            element("label", {}, [document.createTextNode("Model"), model]),
            element("label", { className: "amt-inline" }, [enabled, document.createTextNode(" Show translations under lyrics")]),
          ])
        )
      }
    }
  )
}

function openSettings() {
  const appState = window.CiderApp?.appState
  if (appState) {
    appState.settingsDeepLinkPluginId = plugin.identifier
    appState.settingsDeepLinkTab = "plugins"
  }
  window.CiderApp?.dialogs?.settings?.("plugins")
}

// A top-bar button opens the settings in place, and the Plugins menu has an
// entry for the full settings page, so the key can be changed at any time.
function addSettingsEntryPoints() {
  const components = window.__PLUGINSYS__?.Components
  components?.CustomButtons?.addCustomButton?.({
    location: "chrome-top/right",
    title: "Lyrics Translator",
    element: "文A",
    menuElement: "amt-translator-settings",
  })
  components?.MainMenu?.addMenuItem?.({ label: "Lyrics Translator settings…", onClick: openSettings })
}

let started = false

function startPlugin(notifications) {
  if (started) return
  started = true
  ensureStyles()
  createSettingsElement()
  addSettingsEntryPoints()
  if (ciderStore("lyric-store")) {
    installLyricsGate()
    startStoreMode(notifications)
  }
  else startDOMMode(notifications)
}

const PROVIDER_TIMEOUT_MS = 5000

function notFoundResponse() {
  return new Response(JSON.stringify({ code: "NOT_FOUND" }), { status: 404, headers: { "Content-Type": "application/json" } })
}

async function fetchWithTimeout(realFetch, input, init, ms) {
  const controller = new AbortController()
  init?.signal?.addEventListener?.("abort", () => controller.abort(init.signal.reason), { once: true })
  const timer = setTimeout(() => controller.abort(), ms)
  try {
    return await realFetch(input, { ...init, signal: controller.signal })
  } catch (error) {
    if (controller.signal.aborted && !init?.signal?.aborted) return new Response("", { status: 504 })
    throw error
  } finally {
    clearTimeout(timer)
  }
}

async function appleHasLyrics(id) {
  try {
    const response = await withTimeout(
      window.CiderApp.v3(`/v1/catalog/$STOREFRONT/songs/${id}/lyrics`, {}, { skipLanguage: true, suppressServiceIssue: true }),
      PROVIDER_TIMEOUT_MS
    )
    return ttmlLineTexts(response?.data?.data?.[0]?.attributes?.ttml).some(Boolean)
  } catch {
    return false
  }
}

// Cider asks user-submitted lyrics, Apple Music, Musixmatch and NetEase in
// turn, waiting up to 35 s on each, and keeps going after Apple Music when its
// lyrics are unsynced. This answers the other providers with "not found" when
// Apple Music has lyrics for the song, and gives them 5 s otherwise.
function installLyricsGate() {
  const realFetch = window.fetch.bind(window)
  const appleChecks = new Map()
  const namesToIds = new Map()
  const checkApple = (id) => {
    if (!appleChecks.has(id)) appleChecks.set(id, appleHasLyrics(id))
    return appleChecks.get(id)
  }
  const idForQuery = (query) => {
    const key = lineKey(query)
    for (const [name, id] of namesToIds) if (name && key.includes(name)) return id
    return null
  }

  window.fetch = async (input, init) => {
    const url = typeof input === "string" ? input : input?.url ?? String(input)
    const request = thirdPartyLyricsRequest(url, init?.body)
    if (!request) return realFetch(input, init)
    // NetEase also supplies Chinese translations; leave it alone for those.
    if (request.provider === "netease" && String(window.CiderApp?.config?.getValue?.("lyrics.translationLanguage") ?? "").startsWith("zh")) {
      return realFetch(input, init)
    }
    if (request.id && request.name) namesToIds.set(lineKey(request.name), request.id)
    const id = request.id ?? idForQuery(request.query ?? "")
    if (id && (await checkApple(id))) return notFoundResponse()
    return fetchWithTimeout(realFetch, input, init, PROVIDER_TIMEOUT_MS)
  }
}

// Cider's Rise server translates Apple Music and user-submitted TTML with
// machine translation. A finished translation is cached there for everyone.
async function riseCachedTranslation(id, code, ttml) {
  try {
    const response = await withTimeout(fetch(`${RISE_LYRICS_API}/ttml/translations/${encodeURIComponent(id)}/${code}`), 1500)
    if (!response?.ok) return null
    const json = await response.json()
    const pairs = (json.translations ?? []).map((t) => ({ line: t.originalText, translation: t.translatedText }))
    return pairs.length ? pairs : null
  } catch {
    return null
  }
}

async function riseMachineTranslation(id, ttml, sourceLanguage, targetLanguage) {
  try {
    const response = await fetch(`${RISE_LYRICS_API}/ttml/translate`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id, ttml, sourceLanguage, targetLanguage }),
    })
    if (!response.ok) return null
    const json = await response.json()
    if (json.status === "completed" && json.translatedTtml) {
      const pairs = pairsFromTranslatedTtml(ttml, json.translatedTtml)
      return pairs.length ? pairs : null
    }
    for (let attempt = 0; attempt < 30; attempt += 1) {
      await new Promise((resolve) => setTimeout(resolve, 3000))
      const pairs = await riseCachedTranslation(id, targetLanguage, ttml)
      if (pairs) return pairs
    }
  } catch {}
  return null
}

// Cider 4: translations are written onto the lines in Cider's lyric store, so
// Cider renders them in its own translation slot for static, line-synced and
// word-synced lyrics alike. Cider's own translations always win.
function startStoreMode(notifications) {
  const store = ciderStore("lyric-store")
  const persistent = createPersistentCache(localStorage)
  const owned = new WeakMap()
  const translations = new Map()
  const jobs = new Map()
  let scheduled = false

  const entriesFor = (id) => store.lyricStore.filter((entry) => String(entry.songId) === id)

  const decodeLines = (entries) => {
    for (const entry of entries) {
      for (const line of entry.lyrics ?? []) {
        if (typeof line.text === "string" && line.text.includes("&")) line.text = decodeEntities(line.text)
        for (const word of line.words ?? []) {
          if (typeof word.text === "string" && word.text.includes("&")) word.text = decodeEntities(word.text)
        }
      }
    }
  }

  const sync = () => {
    scheduled = false
    const settings = loadSettings()
    if (!settings.enabled) {
      for (const entry of store.lyricStore) clearOwnedTranslations(entry.lyrics, owned)
      return
    }
    for (const song of wantedSongs()) {
      const entries = entriesFor(song.id)
      if (entries.length === 0) continue
      decodeLines(entries)
      const key = `${song.id}|${settings.language}`
      if (!jobs.has(key)) jobs.set(key, translateSong(song, entries, settings, key))
      const byKey = translations.get(key)
      if (byKey) for (const entry of entries) applyTranslationsToLines(entry.lyrics, byKey, owned)
    }
  }

  const scheduleSync = () => {
    if (scheduled) return
    scheduled = true
    queueMicrotask(sync)
  }

  const useTranslations = (key, byKey) => {
    translations.set(key, byKey)
    scheduleSync()
  }

  async function officialTranslations(id, language) {
    const code = LANGUAGE_CODES[language]
    if (!code) return null
    const stored = store.getTranslations?.(id, code)
    if (stored?.translations?.length) {
      return stored.translations.map((t) => ({ line: t.matched_line, translation: t.translation }))
    }
    const lookup = window.CiderApp?.RPC?.getLyricsTranslations?.(id, code)
    const result = lookup ? await withTimeout(Promise.resolve(lookup).catch(() => null), 1500) : null
    return result?.ok && result.translations?.length ? result.translations : null
  }

  // Every song gets a translation request, whichever provider its lyrics came
  // from: official or already-made translations first, then DeepSeek, with
  // Cider's own machine translation started alongside as the fallback.
  async function translateSong(song, entries, settings, key) {
    const code = LANGUAGE_CODES[settings.language]
    const entry = entries[0]
    const lines = entry.lyrics.map((line) => decodeEntities(line.text ?? "").trim())
    const show = (source, pairsOrByKey, isPairs = true) => {
      const byKey = isPairs ? alignTranslations(lines, pairsOrByKey) : pairsOrByKey
      for (const current of entriesFor(song.id)) clearOwnedTranslations(current.lyrics, owned)
      persistent.set(song.id, settings.language, { source, translations: byKey })
      useTranslations(key, byKey)
    }

    // A replay shows the saved translation at once. Official translations
    // still replace a saved DeepSeek or machine translation.
    const saved = persistent.get(song.id, settings.language)
    const savedTranslations = saved?.translations ?? saved
    if (savedTranslations) useTranslations(key, savedTranslations)
    if (saved?.source === "official") return

    const sourceLanguage = detectLanguage(lines.filter(Boolean), entry.info?.language)
    if (code && sourceLanguage === code) return

    try {
      const official = await officialTranslations(song.id, settings.language)
      if (official) return show("official", official)
      if (savedTranslations || entries.some((current) => hasForeignTranslations(current.lyrics, owned))) return

      const machineReady = entry.ttml && code ? await riseCachedTranslation(song.id, code, entry.ttml) : null
      if (machineReady) return show("cider", machineReady)
      const machine = entry.ttml && code ? riseMachineTranslation(song.id, entry.ttml, sourceLanguage, code) : null

      try {
        const byKey = {}
        translations.set(key, byKey)
        const result = await streamTranslateLines(linesToTranslate(lines, settings.language), song.track, settings.language, settings.model, settings.apiKey, fetch, (line, translation) => {
          byKey[lineKey(line)] = translation
          scheduleSync()
        })
        Object.assign(byKey, translationsByLineKey(result))
        persistent.set(song.id, settings.language, { source: "deepseek", translations: byKey })
        scheduleSync()
      } catch (error) {
        const fallback = machine ? await machine : null
        if (fallback) return show("cider", fallback)
        throw error
      }
    } catch (error) {
      reportError(notifications, error.message)
      // Temporary failures are retried later; a declined song or a bad key is
      // not, so a failing song does not keep costing requests.
      if (error instanceof TranslationError && error.isRetryable) setTimeout(() => jobs.delete(key), 60_000)
    }
  }

  store.$subscribe?.(scheduleSync, { detached: true })
  setInterval(sync, 500)
  document.addEventListener("amt-settings-changed", () => {
    for (const entry of store.lyricStore) clearOwnedTranslations(entry.lyrics, owned)
    jobs.clear()
    translations.clear()
    sync()
  })
  sync()
}

// Older Cider builds without a lyric store: match LRCLIB lyrics to the lines
// on screen and add our own label under each one.
function startDOMMode(notifications) {
  const cache = createMemoryCache()
  let currentKey = ""
  let currentTranslations = {}
  let loading = false
  let waitingForLyricsView = ""
  // Lyrics on screen when the track changed belong to the previous track until
  // Cider swaps them, so the fallback must not translate them.
  let staleSignature = ""
  let currentTrackKey = ""
  const freshDisplayedLines = () => (displayedSignature() === staleSignature ? [] : displayedLines())

  const tick = async () => {
    decodeLyricEntities()
    const settings = loadSettings()
    if (!settings.enabled) {
      document.querySelectorAll(".amt-translation").forEach((node) => node.remove())
      return
    }
    const track = nowPlayingTrack()
    if (!track) return
    const key = `${cacheKey(track)}|${settings.language}|${settings.model}`
    if (key === waitingForLyricsView && lyricNodes().length > 0 && displayedSignature() !== staleSignature) {
      waitingForLyricsView = ""
      currentKey = ""
    }
    if (key !== currentKey && !loading) {
      loading = true
      if (currentTrackKey && currentTrackKey !== cacheKey(track)) staleSignature = displayedSignature()
      currentTrackKey = cacheKey(track)
      currentKey = key
      try {
        const result = await loadTranslatedLyrics(track, settings, browserHTTP, cache, freshDisplayedLines)
        currentTranslations = translationsByLineKey(result.translations)
        if (result.error) reportError(notifications, result.error)
      } catch (error) {
        currentTranslations = {}
        if (error instanceof LyricsError) waitingForLyricsView = key
        else reportError(notifications, error.message)
      } finally {
        loading = false
      }
    }
    injectTranslations(currentTranslations)
  }

  setInterval(tick, 400)
  document.addEventListener("amt-settings-changed", () => {
    currentKey = ""
    tick()
  })
  tick()
}

function reportError(notifications, message) {
  console.warn("[Lyrics Translator]", message)
  try {
    notifications?.notify?.({ title: "Lyrics Translator", message })
  } catch {}
}

// Cider 4 imports plugin.js as an ES module and calls setup() on its default
// export, skipping any plugin without pluginKitVersion.
const plugin = {
  name: "Lyrics Translator",
  identifier: "com.jpark9013.apple-music-translator",
  description: "Shows DeepSeek translations under each lyric line in Cider.",
  version: PLUGIN_VERSION,
  author: "jpark9013",
  repo: "https://github.com/jpark9013/AppleMusicTranslator",
  pluginKitVersion: 1,
  SettingsElement: "amt-translator-settings",
  setup({ Notifications } = {}) {
    startPlugin(Notifications)
  },
}

export default plugin

